var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a01 08\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u041c\u0412\u0424 \u0441\u043e\u0432\u0435\u0442\u0443\u0435\u0442 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0443 \u0432\u0432\u0435\u0441\u0442\u0438 \u043d\u0430\u043b\u043e\u0433\u000d\u000a\u0424\u043e\u043d\u0434 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0443 \u0437\u0430\u043d\u044f\u0442\u044c\u0441\u044f \u0431\u044e\u0434\u0436\u0435\u0442\u043e\u043c: \u000d\u000a\u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043d\u0430\u043b\u043e\u0433, \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0441\u0443\u0431\u0441\u0438\u0434\u0438\u0439 \u000d\u000a\u0438 \u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u0430\u044f \u0444\u0438\u0441\u043a\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430. \u0413\u043e\u0441\u0434\u043e\u043b\u0433 \u000d\u000a\u043f\u0440\u0435\u0432\u044b\u0448\u0430\u0435\u0442 110% \u0412\u0412\u041f, \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0432\u044b\u0440\u043e\u0441 \u0434\u043e 11%. \u000d\u000a\u041f\u0440\u043e\u0433\u043d\u043e\u0437 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0433\u043e \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0430 \u0443\u0436\u0435 \u043f\u043e\u043d\u0438\u0436\u0435\u043d, \u000d\u000a\u043f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u044b \u0441\u0442\u0440\u0430\u043d\u044b \u0431\u0435\u0437 \u0440\u0435\u0444\u043e\u0440\u043c \u0442\u0443\u043c\u0430\u043d\u043d\u044b.\u000d\u000a\u041a\u0430\u0442\u0430\u0440\u0441\u043a\u0438\u0439 QIA \u0438 Ivanhoe \u0443\u0433\u043b\u0443\u0431\u043b\u044f\u044e\u0442 \u000d\u000a\u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043f\u043e \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u0430\u043c\u000d\u000a\u0424\u043e\u043d\u0434 \u0431\u0443\u0434\u0435\u0442 \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432, \u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u0434\u043b\u044f \u0414\u0420\u041a. \u0412 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 QIA \u0443\u0436\u0435 \u000d\u000a\u0432\u043b\u043e\u0436\u0438\u043b $500 \u043c\u043b\u043d \u0432 Ivanhoe, \u0432\u044b\u043a\u0443\u043f\u0438\u0432 57,5 \u043c\u043b\u043d \u0430\u043a\u0446\u0438\u0439. \u000d\u000a\u0414\u043e\u043b\u044f \u0444\u043e\u043d\u0434\u0430 \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0435\u0442 4%, \u0430 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u0442\u044c \u0431\u0443\u0434\u0443\u0449\u0438\u0435 M&A.\u000d\u000aAD Ports \u043a\u0443\u043f\u0438\u043b\u0430 19% \u0435\u0433\u0438\u043f\u0435\u0442\u0441\u043a\u043e\u0433\u043e ALCN \u000d\u000a\u0437\u0430 $28 \u043c\u043b\u043d\u000d\u000aALCN \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0434\u0432\u0443\u043c\u044f \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u0430\u043c\u0438 \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u043e\u0439 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 1,5 \u043c\u043b\u043d TEU. \u041f\u043e\u0441\u043b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 SEIC \u000d\u000a\u0432 2022 \u0433\u043e\u0434\u0443 \u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 194%.\u000d\u000aMaersk \u0433\u043e\u0442\u043e\u0432\u0430 \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u000d\u000a\u043f\u0440\u0438 \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0439\u000d\u000a\u0422\u0440\u0430\u043d\u0437\u0438\u0442 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442 \u0434\u043e 15% \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438. \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0443\u0436\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b\u0438 \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u000d\u000a\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432\u043e\u0437\u044b \u043d\u0430 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0441 \u0434\u0435\u043a\u0430\u0431\u0440\u044f, \u000d\u000a\u043d\u043e \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0445 \u0434\u0430\u0442 \u043d\u0435\u0442.\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u043f\u0440\u043e\u0448\u043b\u0438 \u0430\u0443\u0434\u0438\u0442 RMAP\u000d\u000aIFMI \u0438 WMI \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u0441\u0440\u043e\u043a\u043e\u043c \u043d\u0430 \u0433\u043e\u0434. \u000d\u000a\u0412 Weda Bay \u0442\u0435\u043f\u0435\u0440\u044c \u0447\u0435\u0442\u044b\u0440\u0435 \u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u000d\u000a\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0443 \u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a.\u000d\u000aBrunswick \u043d\u0430\u0447\u0430\u043b\u0430 \u043f\u043e\u0438\u0441\u043a \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0433\u043e \u043b\u0438\u0442\u0438\u044f\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0440\u0438\u0441\u0442\u0443\u043f\u0438\u043b\u0430 \u043a \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0435 \u043d\u0430 \u0443\u0447\u0430\u0441\u0442\u043a\u0435 \u2028\u000d\u000a\u0432 84,67 \u043a\u043c\u00b2 \u043a \u0432\u043e\u0441\u0442\u043e\u043a\u0443 \u043e\u0442 \u042d\u0440 \u0420\u0438\u044f\u0434\u0430. \u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0445\u043e\u0447\u0435\u0442 \u000d\u000a\u0441\u0442\u0430\u0442\u044c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432, \u0430 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043b\u0438\u0442\u0438\u044f \u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441 2027 \u0433\u043e\u0434\u0430.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f Amak \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u043b\u0430 \u043d\u043e\u0432\u044b\u0435 \u000d\u000a\u0437\u0430\u043b\u0435\u0436\u0438 \u043c\u0435\u0434\u0438 \u0438 \u0434\u0440\u0430\u0433\u043e\u0446\u0435\u043d\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432\u000d\u000a\u041d\u0430 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0443\u0447\u0430\u0441\u0442\u043a\u0435 \u0432 \u041d\u0430\u0434\u0436\u0440\u0430\u043d\u0435 \u0432\u044b\u044f\u0432\u043b\u0435\u043d\u043e \u000d\u000a\u043f\u043e\u0447\u0442\u0438 11 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445. \u0420\u0430\u0437\u0432\u0435\u0434\u043a\u0430 \u000d\u000a\u043e\u0445\u0432\u0430\u0442\u0438\u043b\u0430 \u043b\u0438\u0448\u044c 10% \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438. \u041f\u043e\u0434\u0440\u043e\u0431\u043d\u044b\u0439 \u043e\u0442\u0447\u0435\u0442 \u000d\u000a\u043e\u0431 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u0442 \u0432\u043e \u0432\u0442\u043e\u0440\u043e\u0439 \u000d\u000a\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0435 2026 \u0433\u043e\u0434\u0430.\u000d\u000aHapag-Lloyd \u043d\u0435 \u0442\u043e\u0440\u043e\u043f\u0438\u0442\u0441\u044f \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u000d\u000a\u0432 \u0421\u0443\u044d\u0446\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u0435 \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u000d\u000a\u043c\u043e\u0440\u0435, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0440\u0430\u043d\u0437\u0438\u0442 \u043d\u0435\u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u044b\u043c. \u000d\u000a\u0417\u0430\u0434\u0435\u0440\u0436\u043a\u0438 \u0438 \u043e\u0431\u0445\u043e\u0434 \u0410\u0444\u0440\u0438\u043a\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442 \u0443\u0434\u043e\u0440\u043e\u0436\u0430\u0442\u044c \u000d\u000a\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043a\u0438.\u000d\u000aMMG \u043e\u0442\u043b\u043e\u0436\u0438\u043b\u0430 \u043f\u043e\u043a\u0443\u043f\u043a\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u000d\u000aAnglo American\u000d\u000a\u0421\u0434\u0435\u043b\u043a\u0443 \u043d\u0430 $500 \u043c\u043b\u043d \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u043b\u0438 \u0434\u043e \u0438\u044e\u043d\u044f 2026 \u0433\u043e\u0434\u0430 \u2028\u000d\u000a\u0438\u0437 \u0437\u0430 \u0443\u0433\u043b\u0443\u0431\u043b\u0435\u043d\u043d\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0415\u0432\u0440\u043e\u043a\u043e\u043c\u0438\u0441\u0441\u0438\u0438. \u0420\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u000d\u000a\u043e\u043f\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0444\u0435\u0440\u0440\u043e\u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u0432 \u0415\u0432\u0440\u043e\u043f\u0443.\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u0432\u0432\u043e\u0434\u0438\u0442 \u043f\u043e\u0448\u043b\u0438\u043d\u0443 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430\u000d\u000a\u0421\u0442\u0430\u0432\u043a\u0430 \u0431\u0443\u0434\u0435\u0442 7,5\u201315% \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0446\u0435\u043d. \u000d\u000a\u0411\u044e\u0434\u0436\u0435\u0442 \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u043e\u043a\u043e\u043b\u043e $360 \u043c\u043b\u043d. \u041f\u043e\u0445\u043e\u0436\u0438\u0435 \u043c\u0435\u0440\u044b \u000d\u000a\u043e\u0431\u0441\u0443\u0436\u0434\u0430\u044e\u0442\u0441\u044f \u0442\u0430\u043a\u0436\u0435 \u0434\u043b\u044f \u0443\u0433\u043b\u044f \u0438 \u0440\u044f\u0434\u0430 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432.","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u041c\u0412\u0424 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043b \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0443 \u0432\u0432\u0435\u0441\u0442\u0438 \u000d\u000a\u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043d\u0430\u043b\u043e\u0433\u000d\u000a\u0421\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0439\u0442\u0438\u043d\u0433 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0443\u0436\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 S&P Global \u0438\u0437-\u0437\u0430 \u0440\u043e\u0441\u0442\u0430 \u000d\u000a\u0433\u043e\u0441\u0434\u043e\u043b\u0433\u0430 \u0438 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u0430.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0443 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043e \u0432\u0432\u0435\u0441\u0442\u0438 \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u000d\u000a\u043f\u043e\u0434\u043e\u0445\u043e\u0434\u043d\u044b\u0439 \u043d\u0430\u043b\u043e\u0433 \u0438 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u000d\u000a\u0441\u0443\u0431\u0441\u0438\u0434\u0438\u0438 \u0434\u043b\u044f \u0443\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u044f \u0431\u044e\u0434\u0436\u0435\u0442\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a \u041c\u0412\u0424 \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0438\u0439 \u000d\u000a\u0441 \u0432\u043b\u0430\u0441\u0442\u044f\u043c\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u0424\u043e\u043d\u0434 \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0430\u044f \u043f\u043e\u0437\u0438\u0446\u0438\u044f \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u0443\u0445\u0443\u0434\u0448\u0438\u043b\u0430\u0441\u044c: \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0434\u043e\u0441\u0442\u0438\u0433 11% \u0412\u0412\u041f, \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442\u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u043b\u0433 \u2014 110% \u0412\u0412\u041f. \u0413\u043b\u0430\u0432\u0430 \u000d\u000a\u043c\u0438\u0441\u0441\u0438\u0438 \u041c\u0412\u0424 \u0414\u0436\u043e\u043d \u0411\u043b\u043e\u0439\u0434\u043e\u0440\u043d \u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u0434\u043b\u044f \u000d\u000a\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0433\u043e \u0440\u043e\u0441\u0442\u0430 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0443 \u043d\u0443\u0436\u043d\u0430 \u000d\u000a\u043c\u043d\u043e\u0433\u043e\u043b\u0435\u0442\u043d\u044f\u044f \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u0444\u0438\u0441\u043a\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u043a\u043e\u043d\u0441\u043e\u043b\u0438\u0434\u0430\u0446\u0438\u0438 \u0432 \u0441\u043e\u0447\u0435\u0442\u0430\u043d\u0438\u0438 \u0441\u043e \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u043c\u0438 \u000d\u000a\u0440\u0435\u0444\u043e\u0440\u043c\u0430\u043c\u0438.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0430\u0442\u0430\u0440\u0441\u043a\u0438\u0439 QIA \u0438 Ivanhoe \u0431\u0443\u0434\u0443\u0442 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0430\u0442\u044c \u2028\u000d\u000a\u0432 \u0441\u0444\u0435\u0440\u0435 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432\u000d\u000a\u041a\u0430\u0442\u0430\u0440 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0439 \u0446\u0435\u043f\u043e\u0447\u043a\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441 \u043a\u0440\u0443\u043f\u043d\u044b\u043c \u0438\u0433\u0440\u043e\u043a\u043e\u043c \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u0410\u0444\u0440\u0438\u043a\u0438.\u000d\u000aQIA \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0442 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u0438 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u0432 \u0414\u0420\u041a. \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0442\u0430\u043a\u0436\u0435 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u044e\u0442 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u000d\u000a\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0442\u044c \u043e\u0431\u044a\u0435\u043c\u044b \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0438 \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0442\u044c \u000d\u000a\u0441\u0434\u0435\u043b\u043a\u0438 M&A. \u041e\u0431 \u044d\u0442\u043e\u043c Ivanhoe. \u000a\u000d\u000a\u0412 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 QIA \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043b \u0432 Ivanhoe \u2028\u000d\u000a$500 \u043c\u043b\u043d, \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u044f 57,5 \u043c\u043b\u043d \u0430\u043a\u0446\u0438\u0439 \u043f\u043e $8,7 \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442\u000d\u000a\u0437\u0430 \u0431\u0443\u043c\u0430\u0433\u0443. \u0414\u043e\u043b\u044f \u0444\u043e\u043d\u0434\u0430 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u0441\u0434\u0435\u043b\u043a\u0438 \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 4%.\u000a\u000d\u000aIvanhoe Mines \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u043a\u0440\u0443\u043f\u043d\u044b\u043c\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430\u043c\u0438 \u000d\u000a\u0432 \u042e\u0410\u0420 \u0438 \u0414\u0420\u041a. \u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u043e\u043d\u0430 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u0435\u0442 \u000d\u000a\u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043e\u0447\u043d\u044b\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u043d\u0430 \u043e\u0441\u0430\u0434\u043e\u0447\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0434\u043d\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445 \u0432 \u0410\u043d\u0433\u043e\u043b\u0435, \u041a\u0430\u0437\u0430\u0445\u0441\u0442\u0430\u043d\u0435 \u000d\u000a\u0438 \u0417\u0430\u043c\u0431\u0438\u0438.\u000d\u000a02 08","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0430\u043d\u0430\u0434\u0441\u043a\u0430\u044f Brunswick Exploration \u043d\u0430\u0447\u0430\u043b\u0430 \u043f\u043e\u0438\u0441\u043a\u0438 \u000d\u000a\u043b\u0438\u0442\u0438\u044f \u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438\u000d\u000a\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0445\u043e\u0447\u0435\u0442 \u0441\u0442\u0430\u0442\u044c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0438 \u0443\u0441\u043a\u043e\u0440\u044f\u0435\u0442 \u000d\u000a\u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443.\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0435\u0440\u0432\u044b\u043c \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u000d\u000a\u043d\u0430 \u0442\u0432\u0435\u0440\u0434\u044b\u0435 \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0435 \u0440\u0443\u0434\u044b \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435\u043c, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u000d\u000a\u043f\u043e \u0432\u0441\u0435\u0439 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430.\u000d\u000a\u0441\u0442\u0430\u043b\u0430 \u0420\u0430\u043d\u0435\u0435 Saudi Aramco \u0438 Maaden \u0441\u043e\u0437\u0434\u0430\u043b\u0438 \u000d\u000a\u0421\u041f \u0434\u043b\u044f \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043d\u043e\u0432\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u000d\u000a\u0438 \u0441\u043e\u0431\u0438\u0440\u0430\u044e\u0442\u0441\u044f \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u043e\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043b\u0438\u0442\u0438\u044f \u0432 2027 \u0433\u043e\u0434\u0443.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f Amak \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u043b\u0430 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043c\u0435\u0434\u0438, \u000d\u000a\u0446\u0438\u043d\u043a\u0430, \u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u0430\u000d\u000a\u0420\u0430\u0437\u0432\u0435\u0434\u043a\u0430 \u043e\u0445\u0432\u0430\u0442\u0438\u043b\u0430 \u0442\u043e\u043b\u044c\u043a\u043e 10% \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438, \u043d\u043e \u043e\u0446\u0435\u043d\u043a\u0438 \u0443\u0436\u0435 \u043e\u0431\u0435\u0449\u0430\u044e\u0442 \u043f\u043e\u0447\u0442\u0438 11 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432.\u000d\u000aAmak \u043d\u043e\u0432\u044b\u0435 \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438, \u0446\u0438\u043d\u043a\u0430, \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u0430 \u043d\u0430 \u0443\u0447\u0430\u0441\u0442\u043a\u0435 \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u000d\u000a\u041d\u0430\u0434\u0436\u0440\u0430\u043d. \u0420\u0430\u0431\u043e\u0442\u044b \u043d\u0430\u0447\u0430\u043b\u0438\u0441\u044c \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0439 \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 2024 \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u0412 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 2024 \u0433\u043e\u0434\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430 \u000d\u000a\u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043d\u0430 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u0443\u0447\u0430\u0441\u0442\u043a\u043e\u0432 \u042d\u043b\u044c-\u0425\u0438\u0434\u0436\u0440\u0430 \u000d\u000a\u0438 \u0414\u0436\u0430\u0431\u0430\u043b\u044c \u041a\u0430\u0440\u043d \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u041d\u0430\u0434\u0436\u0440\u0430\u043d \u000d\u000a\u043e\u0431\u0449\u0435\u0439 \u043f\u043b\u043e\u0449\u0430\u0434\u044c\u044e 274 \u043a\u043c2. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u0432 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u043c \u0433\u043e\u0434\u0443, \u000d\u000a\u0430 \u043e\u0442\u0447\u0435\u0442 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432\u043e \u0432\u0442\u043e\u0440\u043e\u0439 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0435 \u000d\u000a2026 \u0433\u043e\u0434\u0430.\u000d\u000a\u0432\u044b\u044f\u0432\u0438\u043b\u0430\u000d\u000a03 08","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000aAD Ports \u043a\u0443\u043f\u0438\u043b\u0430 \u0443 SEIC 19% \u0430\u043a\u0446\u0438\u0439 \u0435\u0433\u0438\u043f\u0435\u0442\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u043e\u0440\u0442\u043e\u0432\u043e\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0437\u0430 $28 \u043c\u043b\u043d\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430 AD Ports \u043a\u0443\u043f\u0438\u043b\u0430 19% \u0430\u043a\u0446\u0438\u0439 \u0435\u0433\u0438\u043f\u0435\u0442\u0441\u043a\u043e\u0433\u043e \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u000d\u000aAlexandria Container & Cargo Handling Company (ALCN), \u0432 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0438 AD Ports. \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000aALCN \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0434\u0432\u0443\u043c\u044f \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u0430\u043c\u0438 \u000d\u000a\u0432 \u0410\u043b\u0435\u043a\u0441\u0430\u043d\u0434\u0440\u0438\u0438 \u0438 \u0414\u0435\u043a\u0445\u0435\u0439\u043b\u0435 \u043d\u0430 \u0431\u0435\u0440\u0435\u0433\u0443 \u000d\u000a\u0421\u0440\u0435\u0434\u0438\u0437\u0435\u043c\u043d\u043e\u0433\u043e \u043c\u043e\u0440\u044f. \u0418\u0445 \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 1,5 \u043c\u043b\u043d TEU \u043f\u0440\u0438 \u0443\u0440\u043e\u0432\u043d\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u000d\u000a\u043e\u043a\u043e\u043b\u043e 71%.\u000d\u000aSaudi Egyptian Investment Company (SEIC) \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u043c\u0443 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u043c\u0443 \u0444\u043e\u043d\u0434\u0443 \u000d\u000aPublic Investment Fund. \u041f\u043e\u0441\u043b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 SEIC \u000d\u000a\u0432 2022 \u0433\u043e\u0434\u0443 \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u0430\u044f \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u000d\u000aALCN \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 194%.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aMaersk \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u0438\u0442 \u0442\u0440\u0430\u043d\u0437\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u2028\u000d\u000a\u043f\u0440\u0438 \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0439\u000d\u000a\u0422\u0440\u0430\u043d\u0437\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u0434\u043e 15% \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438, \u044d\u0442\u043e \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u000d\u000a\u043c\u0435\u0436\u0434\u0443 \u0415\u0432\u0440\u043e\u043f\u043e\u0439 \u0438 \u0410\u0437\u0438\u0435\u0439. \u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043f\u043e \u043d\u0435\u043c\u0443 \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u043b\u043e \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u2028\u000d\u000a36 \u0441\u0443\u0434\u043e\u0432 \u0432\u0434\u0432\u043e\u0435 \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0432 2023 \u0433\u043e\u0434\u0443.\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0432\u0435\u0440\u043d\u0435\u0442\u0441\u044f \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u0438 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u000d\u000a\u043a\u0430\u043d\u0430\u043b, \u043a\u043e\u0433\u0434\u0430 \u043d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u044f \u0441\u0442\u0430\u043d\u0435\u0442 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0439. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0433\u0435\u043d\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 Maersk \u0412\u0438\u043d\u0441\u0435\u043d\u0442 \u041a\u043b\u0435\u0440\u043a \u000d\u000a \u043d\u0430 \u043f\u0440\u0435\u0441\u0441 \u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0438 \u0432 \u0415\u0433\u0438\u043f\u0442\u0435.\u000a\u000d\u000a\u0427\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0442\u0440\u0430\u043d\u0437\u0438\u0442\u0430 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u000d\u000a\u0441 \u043d\u0430\u0447\u0430\u043b\u0430 \u0434\u0435\u043a\u0430\u0431\u0440\u044f, \u043f\u043e \u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u043e\u0446\u0435\u043d\u043a\u0435\u000d\u000a\u0421\u0443\u044d\u0446\u043a\u043e\u0433\u043e \u043a\u0430\u043d\u0430\u043b\u0430, \u043d\u043e Maersk \u043f\u043e\u043a\u0430 \u043d\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u000d\u000a\u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0445 \u0434\u0430\u0442. \u0421 \u043d\u043e\u044f\u0431\u0440\u044f 2023 \u0433\u043e\u0434\u0430 \u0445\u0443\u0441\u0438\u0442\u044b \u000d\u000a\u0430\u0442\u0430\u043a\u043e\u0432\u0430\u043b\u0438 \u0431\u043e\u043b\u0435\u0435 100 \u0441\u0443\u0434\u043e\u0432, \u043f\u043e\u0442\u043e\u043f\u0438\u043b\u0438 \u0447\u0435\u0442\u044b\u0440\u0435 \u000d\u000a\u0438 \u0437\u0430\u0445\u0432\u0430\u0442\u0438\u043b\u0438 \u043e\u0434\u043d\u043e. \u0412 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u000d\u000a\u0445\u0443\u0441\u0438\u0442\u043e\u0432 \u043f\u043e\u0433\u0438\u0431\u043b\u0438 \u043a\u0430\u043a \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u043e\u0440\u044f\u043a\u043e\u0432.\u000d\u000a04 08","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aHapag-Lloyd \u043d\u0435 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0431\u044b\u0441\u0442\u0440\u043e \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u000d\u000a\u0432 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b\u000d\u000a\u041d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0437\u0430\u0442\u0438\u0448\u044c\u0435 \u0432 \u0430\u0442\u0430\u043a\u0430\u0445 \u0445\u0443\u0441\u0438\u0442\u043e\u0432, \u0440\u0438\u0441\u043a\u0438 \u0434\u043b\u044f \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432\u044b\u0441\u043e\u043a\u0438\u043c\u0438.\u000d\u000a\u041d\u0435\u043c\u0435\u0446\u043a\u0430\u044f \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Hapag-Lloyd \u000d\u000a\u043d\u0435 \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0442\u044c \u0442\u0440\u0430\u043d\u0437\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u0421\u0443\u044d\u0446, \u043f\u043e\u043a\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u000d\u000a\u043d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u043d\u0430\u044f \u043e\u0431\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0433\u0435\u043d\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0420\u043e\u043b\u044c\u0444 \u0425\u0430\u0431\u0431\u0435\u043d \u042f\u043d\u0441\u0435\u043d. \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0441\u043b\u0435\u0434\u0438\u0442 \u0437\u0430 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0435\u0439, \u043d\u043e \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u000d\u000a\u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043d\u0430 \u043a\u0440\u0430\u0442\u0447\u0430\u0439\u0448\u0438\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u043c\u0435\u0436\u0434\u0443 \u000d\u000a\u0415\u0432\u0440\u043e\u043f\u043e\u0439 \u0438 \u0410\u0437\u0438\u0435\u0439 \u043f\u0440\u0435\u0436\u0434\u0435\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u043c.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u041b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u0440\u0438\u0437\u0438\u0441 \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u043c\u043e\u0440\u0435 \u043d\u0430\u0447\u0430\u043b\u0441\u044f \u000d\u000a\u0441 \u043f\u0435\u0440\u0432\u044b\u043c\u0438 \u043d\u0430\u043f\u0430\u0434\u0435\u043d\u0438\u044f\u043c\u0438 \u0445\u0443\u0441\u0438\u0442\u043e\u0432 \u0432 \u043d\u043e\u044f\u0431\u0440\u0435 \u000d\u000a2023 \u0433\u043e\u0434\u0430. \u041f\u043e\u0441\u043b\u0435 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043e\u0433\u043d\u044f \u0432 \u0441\u0435\u043a\u0442\u043e\u0440\u0435 \u000d\u000a\u0413\u0430\u0437\u0430 \u043b\u0438\u0434\u0435\u0440 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f \u0440\u0430\u0441\u043f\u043e\u0440\u044f\u0434\u0438\u043b\u0441\u044f \u000d\u000a\u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0443\u0434\u0430\u0440\u044b, \u043f\u043e\u043a\u0430 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u000d\u000a\u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0435\u0442\u0441\u044f. \u0421\u0435\u0439\u0447\u0430\u0441 \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u043d\u044b\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0432\u044b\u043d\u0443\u0436\u0434\u0435\u043d\u044b \u0438\u0434\u0442\u0438 \u0432 \u043e\u0431\u0445\u043e\u0434 \u0410\u0444\u0440\u0438\u043a\u0438 \u0447\u0435\u0440\u0435\u0437 \u043c\u044b\u0441 \u000d\u000a\u0414\u043e\u0431\u0440\u043e\u0439 \u041d\u0430\u0434\u0435\u0436\u0434\u044b, \u0447\u0442\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u000d\u000a\u0438 \u0441\u0440\u043e\u043a\u0438 \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0438.\u000d\u000a#\u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0438\u000d\u000a2 \u0434\u0435\u043a\u0430\u0431\u0440\u044f, \u041d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0435\u043d\u044c \u041e\u0410\u042d\u000d\u000a\u042d\u0442\u043e \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u043e\u0432, \u043f\u043e\u0441\u0432\u044f\u0449\u0435\u043d\u043d\u044b\u0439 \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044e \u0444\u0435\u0434\u0435\u0440\u0430\u0446\u0438\u0438.\u000d\u000a05 08","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0438\u000d\u000a16 \u0434\u0435\u043a\u0430\u0431\u0440\u044f, \u041d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0435\u043d\u044c \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430\u000d\u000a\u041f\u0440\u0430\u0437\u0434\u043d\u0438\u043a \u043f\u043e\u0441\u0432\u044f\u0449\u0435\u043d \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u044e \u043e\u0442 \u0431\u0440\u0438\u0442\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0442\u0435\u043a\u0442\u043e\u0440\u0430\u0442\u0430.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aMMG \u043e\u0442\u043b\u043e\u0436\u0438\u043b\u0430 \u043f\u043e\u043a\u0443\u043f\u043a\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 Anglo \u000d\u000aAmerican \u0434\u043e \u0438\u044e\u043d\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a\u0417\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u0441\u0432\u044f\u0437\u0430\u043d\u0430 \u0441 \u0443\u0433\u043b\u0443\u0431\u043b\u0435\u043d\u043d\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u043e\u0439 \u0415\u0432\u0440\u043e\u043a\u043e\u043c\u0438\u0441\u0441\u0438\u0438.\u000d\u000aMMG \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u043b\u0430 \u0441\u0440\u043e\u043a \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f \u0441\u0434\u0435\u043b\u043a\u0438 \u000d\u000a\u043d\u0430 $500 \u043c\u043b\u043d \u043f\u043e \u043f\u043e\u043a\u0443\u043f\u043a\u0435 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u000d\u000aAnglo American \u0432 \u0411\u0440\u0430\u0437\u0438\u043b\u0438\u0438, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f. \u0418\u0437\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u043e \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u0435 \u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043b\u043e\u0441\u044c \u0432 \u043d\u043e\u044f\u0431\u0440\u0435, \u043d\u043e \u0415\u0432\u0440\u043e\u043a\u043e\u043c\u0438\u0441\u0441\u0438\u044f \u000d\u000a\u043d\u0430\u0447\u0430\u043b\u0430 \u0443\u0433\u043b\u0443\u0431\u043b\u0435\u043d\u043d\u0443\u044e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443, \u043e\u043f\u0430\u0441\u0430\u044f\u0441\u044c \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0444\u0435\u0440\u0440\u043e\u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0415\u0432\u0440\u043e\u043f\u0443.\u000a\u000d\u000a\u0410\u043a\u0442\u0438\u0432\u044b \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442 \u0440\u0443\u0434\u043d\u0438\u043a\u0438 Barro Alto \u000d\u000a\u0438 Niquelandia, \u0437\u0430\u0432\u043e\u0434\u044b Barro Alto \u0438 Codemin, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u0433\u0440\u0438\u043d\u0444\u0438\u043b\u0434\u044b Jacare \u0441 \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c\u0438 \u2028\u000d\u000a\u0432 300 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0438 Morro Sem Bone \u2014 \u2028\u000d\u000a\u0432 65 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u000a\u000d\u000aMMG \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0441 \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u043c \u000d\u000a\u0434\u043b\u044f \u0441\u043a\u043e\u0440\u0435\u0439\u0448\u0435\u0433\u043e \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u044f \u0441\u0434\u0435\u043b\u043a\u0438.\u000d\u000a06 08","\u041a\u0438\u0442\u0430\u0439 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0414\u0432\u0430 \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u043d\u0438\u043a\u0435\u043b\u044f \u043f\u0440\u043e\u0448\u043b\u0438 \u000d\u000a\u0430\u0443\u0434\u0438\u0442 RMAP\u000d\u000a\u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u044b \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442 \u0433\u043e\u0434 \u0438 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438.\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 IFMI \u0438 WMI \u0438\u0437 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043f\u0430\u0440\u043a\u0430 Weda Bay \u0430\u0443\u0434\u0438\u0442 \u0438\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u044b \u000d\u000aRMAP, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0430.\u000a\u000d\u000a\u041e\u0431\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u044b \u000d\u000a\u043e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f\u043c \u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0441\u0440\u043e\u043a\u043e\u043c \u043d\u0430 \u0433\u043e\u0434.\u000d\u000a\u043f\u0440\u043e\u0448\u043b\u0438\u000d\u000a\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u043e\u0432 \u000d\u000aWeda Bay \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u043e\u0441\u044c \u0434\u043e \u0447\u0435\u0442\u044b\u0440\u0435\u0445, \u0430 RMAP \u000d\u000a\u0440\u0430\u043d\u0435\u0435 \u0431\u044b\u043b \u043f\u0440\u0438\u0437\u043d\u0430\u043d \u0415\u0432\u0440\u043e\u043a\u043e\u043c\u0438\u0441\u0441\u0438\u0435\u0439.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0437\u0430\u0432\u043e\u0434 QMB \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0438\u043a\u0435\u043b\u044f \u0438\u0437-\u0437\u0430 \u0441\u0431\u043e\u044f \u0432 \u0445\u0432\u043e\u0441\u0442\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0435\u000d\u000a\u0417\u0430\u044f\u0432\u043a\u0430 \u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043d\u043e\u0432\u043e\u0433\u043e \u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430 \u0432\u0441\u0435 \u0435\u0449\u0435 \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u043b\u0430\u0441\u0442\u044f\u043c\u0438.\u000d\u000aQMB New Energy Materials \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0438\u043a\u0435\u043b\u044f. \u041f\u0440\u0438\u0447\u0438\u043d\u0430 \u000d\u000a\u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u043e\u0435 \u0445\u0432\u043e\u0441\u0442\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0435 \u000d\u000a\u0432 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u043f\u0430\u0440\u043a\u0435 \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438. \u000d\u000a\u041f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u043d\u0435 \u0441\u043c\u043e\u0436\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u043d\u0430 \u043f\u043e\u043b\u043d\u0443\u044e \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u043f\u043e \u043c\u0435\u043d\u044c\u0448\u0435\u0439 \u043c\u0435\u0440\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u0434\u0435\u043b\u044c.\u000a\u000d\u000a\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043f\u0430\u0440\u043a\u0430 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0430, \u0447\u0442\u043e \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0435 \u0431\u043b\u0438\u0437\u043a\u043e \u043a \u043f\u0440\u0435\u0434\u0435\u043b\u0443, \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0430 \u0430 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043d\u0430 \u043d\u043e\u0432\u043e\u0435 \u0435\u0449\u0435 \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043e. \u000d\u000a\u0421\u0438\u0442\u0443\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0443\u0441\u0438\u043b\u0435\u043d\u0438\u044f \u000d\u000a\u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430. QMB \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u000d\u000a\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439, \u0433\u0434\u0435 GEM \u0432\u043b\u0430\u0434\u0435\u0435\u0442 63% \u000d\u000a\u0430\u043a\u0446\u0438\u0439, \u0430 Tsingshan 10%.\u000d\u000a07 08","\u041a\u0438\u0442\u0430\u0439 21\u201328 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f\u000d\u000aChengxin Lithium \u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442 Huayou Holdings \u2028\u000d\u000a\u043b\u0438\u0442\u0438\u0439 \u043d\u0430 $2,4 \u043c\u043b\u0440\u0434\u000d\u000a\u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043d\u044b \u043d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0438\u0435 \u043f\u044f\u0442\u044c \u043b\u0435\u0442.\u000d\u000a\u0421 2026 \u043f\u043e 2030 \u0433\u043e\u0434 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a221,4 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u0431\u043e\u043b\u0435\u0435 \u2028\u000d\u000a5% \u0430\u043a\u0446\u0438\u0439 Chengxin Lithium.\u000a\u000d\u000aChengxin Lithium \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 137 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u043b\u0438\u0442\u0438\u0435\u0432\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0432 \u0433\u043e\u0434, \u0432\u043a\u043b\u044e\u0447\u0430\u044f 60 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d\u000d\u000a\u0437\u0430\u043a\u0443\u043f\u0438\u0442 \u2028 \u043d\u0430 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f\u0445 \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438. Huayou \u2028\u000d\u000aHoldings \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043d\u0430\u0447\u0430\u043b \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044e \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u0434\u043e\u0440\u043e\u0433\u0438 \u000d\u000aTAZARA \u0434\u043b\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043c\u0435\u0434\u0438\u000d\u000a\u0420\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442 \u0433\u0440\u0443\u0437\u043e\u043f\u043e\u0442\u043e\u043a \u0432 12 \u0440\u0430\u0437 \u2014 \u0441 200 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0434\u043e 2,4 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434.\u000d\u000a\u041f\u0440\u0435\u043c\u044c\u0435\u0440 \u0413\u043e\u0441\u0441\u043e\u0432\u0435\u0442\u0430 \u041a\u041d\u0420 \u0441\u0442\u0430\u0440\u0442 \u000d\u000a\u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u0434\u043e\u0440\u043e\u0433\u0438 TAZARA \u043c\u0435\u0436\u0434\u0443 \u000d\u000a\u0417\u0430\u043c\u0431\u0438\u0435\u0439 \u0438 \u0422\u0430\u043d\u0437\u0430\u043d\u0438\u0435\u0439. \u041a\u043e\u043d\u0442\u0440\u0430\u043a\u0442 \u043d\u0430 $1,4 \u043c\u043b\u0440\u0434 \u0431\u044b\u043b \u000d\u000a\u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435. \u000a\u000d\u000a\u041a\u043e\u0440\u0438\u0434\u043e\u0440 \u0441\u043e\u0435\u0434\u0438\u043d\u044f\u0435\u0442 \u043c\u0435\u0434\u043d\u044b\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u000d\u000a\u0417\u0430\u043c\u0431\u0438\u0438 \u0438 \u0414\u0420\u041a \u0441 \u043f\u043e\u0440\u0442\u043e\u043c \u0414\u0430\u0440-\u044d\u0441 \u0421\u0430\u043b\u0430\u043c. \u000d\u000a\u0434\u0430\u043b \u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f CRCC \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0438\u0440\u0443\u0435\u0442 \u043f\u0443\u0442\u0438 \u0438 \u043c\u043e\u0441\u0442\u044b \u000d\u000a\u0438 \u043f\u0440\u043e\u043b\u043e\u0436\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 400 \u043a\u043c \u043d\u043e\u0432\u043e\u0439 \u043b\u0438\u043d\u0438\u0438.\u000a\u000d\u000aTAZARA \u0431\u044b\u043b\u0430 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0430 \u0441 \u0443\u0447\u0430\u0441\u0442\u0438\u0435\u043c \u041a\u0438\u0442\u0430\u044f \u000d\u000a\u0432 1970 \u0445 \u0433\u043e\u0434\u0430\u0445 \u0438 \u0438\u043c\u0435\u0435\u0442 \u043f\u0440\u043e\u0442\u044f\u0436\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043e\u043a\u043e\u043b\u043e \u2028\u000d\u000a1,86 \u0442\u044b\u0441. \u043a\u043c.\u000d\u000a#\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0432\u0432\u0435\u0441\u0442\u0438 \u043f\u043e\u0448\u043b\u0438\u043d\u0443 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0440\u044f\u0434\u0430 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432\u000d\u000a\u0415\u0435 \u0440\u0430\u0437\u043c\u0435\u0440 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u043e\u0442 7,5% \u0434\u043e 15%. \u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0433\u043e\u0442\u043e\u0432\u0438\u0442 \u000d\u000a\u0432\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0439 \u043f\u043e\u0448\u043b\u0438\u043d\u044b \u043d\u0430 \u0437\u043e\u043b\u043e\u0442\u043e \u000d\u000a\u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 7,5\u201315% \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u000d\u000a\u0446\u0435\u043d. \u041e\u0431 \u044d\u0442\u043e\u043c \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u0430 \u000d\u000a\u0424\u0435\u0431\u0440\u0438\u043e \u041a\u0430\u043a\u0430\u0440\u0438\u0431\u0443.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u000d\u000a\u041f\u043e \u0440\u0430\u0441\u0447\u0435\u0442\u0430\u043c \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430, \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u000d\u000a\u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u044f \u0441\u043e\u0441\u0442\u0430\u0432\u044f\u0442 \u043e\u043a\u043e\u043b\u043e $360 \u043c\u043b\u043d. \u041f\u043e\u0445\u043e\u0436\u0438\u0435 \u000d\u000a\u043c\u0435\u0440\u044b \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0442\u0430\u043a\u0436\u0435 \u0434\u043b\u044f \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0443\u0433\u043b\u044f \u000d\u000a\u0438 \u0440\u044f\u0434\u0430 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0441 \u0446\u0435\u043b\u044c\u044e \u0441\u0442\u0438\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0440\u0430\u043d\u044b.\u000d\u000a08 08"]